// Files under public/assets. Demo film art is generated by the mobile app's
// scripts/generate-assets.mjs.
export enum AssetPaths {
  BrandMark = '/assets/brand-mark.png',
  AppIcon = '/assets/app-icon.png',
}

const film = (id: string) => ({
  poster: `/assets/films/${id}-poster.jpg`,
  still: `/assets/films/${id}-still.jpg`,
});

export const FilmArt: Record<string, { poster: string; still: string }> = {
  'lautan-pasir': film('lautan-pasir'),
  'gema-malam': film('gema-malam'),
  'arus-biru': film('arus-biru'),
  'rumah-kabut': film('rumah-kabut'),
  'orbit-terakhir': film('orbit-terakhir'),
  'senja-kota-tua': film('senja-kota-tua'),
};
